var converter = new BooleanToBooleanMultiConverter
{
    Mode = BooleanMultiConverterMode.AllTrue,
    TrueValue = true,
    FalseValue = false
};

bool[] conditions = { isValid, isEnabled, hasPermission };
bool result = converter.Convert(conditions, CultureInfo.CurrentCulture);

if (result)
{
    // All conditions are true
    ExecuteOperation();
}

var converter = new BooleanToBooleanMultiConverter
{
    Mode = BooleanMultiConverterMode.AnyTrue,
    NullValue = false,  // Return false if source is null
    EmptyValue = true   // Return true if source array is empty
};

bool resultForNull = converter.Convert(null, CultureInfo.CurrentCulture);  // Returns false
bool resultForEmpty = converter.Convert(Array.Empty<bool>(), CultureInfo.CurrentCulture);  // Returns true

var converter = new BooleanToNegateBooleanConverter();

bool isEnabled = true;
bool result = converter.Convert(isEnabled, CultureInfo.CurrentCulture);
Console.WriteLine(result);  // Output: false

bool backResult = converter.ConvertBack(result, CultureInfo.CurrentCulture);
Console.WriteLine(backResult);  // Output: true

var converter = new BooleanToNegateBooleanConverter();

bool result1 = converter.Convert(true, CultureInfo.CurrentCulture);
Console.WriteLine(result1);  // Output: false

bool result2 = converter.Convert(false, CultureInfo.CurrentCulture);
Console.WriteLine(result2);  // Output: true

var converter = new BooleanToNegateBooleanConverter();

bool original = true;
bool inverted = converter.Convert(original, CultureInfo.CurrentCulture);
bool restored = converter.ConvertBack(inverted, CultureInfo.CurrentCulture);

Console.WriteLine(original);   // Output: true
Console.WriteLine(inverted);   // Output: false
Console.WriteLine(restored);   // Output: true
Console.WriteLine(original == restored);  // Output: true

var converter = new BooleanToVisibilityConverter
{
    TrueValue = Visibility.Visible,
    FalseValue = Visibility.Collapsed
};

bool hasErrors = true;
Visibility result = converter.Convert(hasErrors, CultureInfo.CurrentCulture);
Console.WriteLine(result);  // Output: Visible

bool backResult = converter.ConvertBack(result, CultureInfo.CurrentCulture);
Console.WriteLine(backResult);  // Output: true

// Hide element when condition is true (keeps layout space)
var hideWithSpaceConverter = new BooleanToVisibilityConverter
{
    TrueValue = Visibility.Hidden,
    FalseValue = Visibility.Visible
};

// Show only when true, otherwise collapse
var standardConverter = new BooleanToVisibilityConverter
{
    TrueValue = Visibility.Visible,
    FalseValue = Visibility.Collapsed
};

var converter = new BooleanToVisibilityConverter();

Visibility result1 = converter.Convert(true, CultureInfo.CurrentCulture);
Console.WriteLine(result1);  // Output: Visible

Visibility result2 = converter.Convert(false, CultureInfo.CurrentCulture);
Console.WriteLine(result2);  // Output: Collapsed

var converter = new BooleanToVisibilityConverter();

bool result1 = converter.ConvertBack(Visibility.Visible, CultureInfo.CurrentCulture);
Console.WriteLine(result1);  // Output: true

bool result2 = converter.ConvertBack(Visibility.Collapsed, CultureInfo.CurrentCulture);
Console.WriteLine(result2);  // Output: false

// This would throw NotSupportedException with default configuration
// since Hidden is neither TrueValue nor FalseValue
try
{
    converter.ConvertBack(Visibility.Hidden, CultureInfo.CurrentCulture);
}
catch (NotSupportedException ex)
{
    Console.WriteLine(ex.Message);
}

var converter = new BooleanToVisibilityMultiConverter
{
    Mode = BooleanMultiConverterMode.AllTrue,
    TrueValue = Visibility.Visible,
    FalseValue = Visibility.Collapsed
};

bool[] conditions = { isValid, isEnabled, hasPermission };
Visibility result = converter.Convert(conditions, CultureInfo.CurrentCulture);

if (result == Visibility.Visible)
{
    // All conditions are true
    ShowElement();
