// EnumComboBox.xaml.cs
public partial class EnumComboBox : UserControl
{
    public static readonly DependencyProperty EnumTypeProperty =
        DependencyProperty.Register(
            nameof(EnumType),
            typeof(Type),
            typeof(EnumComboBox));

    public Type EnumType
    {
        get => (Type)GetValue(EnumTypeProperty);
        set => SetValue(EnumTypeProperty, value);
    }

    public EnumComboBox()
    {
        InitializeComponent();
    }
}

var converter = new EnumTypeToNamedEnumValueListConverter
{
    IsAlphabeticallyOrdered = false
};

// Get unsorted list
var unsortedList = converter.Convert(null, typeof(Priority), CultureInfo.CurrentCulture);
// Returns: [Low Priority, Medium Priority, High Priority, Critical]

converter.IsAlphabeticallyOrdered = true;
var sortedList = converter.Convert(null, typeof(Priority), CultureInfo.CurrentCulture);
// Returns: [Critical, High Priority, Low Priority, Medium Priority]

public class StringToUpperConverter : GenericConverter<string, string>
{
    public override string Convert(string source, CultureInfo culture)
    {
        return source?.ToUpper() ?? string.Empty;
    }

    public override string ConvertBack(string result, CultureInfo culture)
    {
        return result?.ToLower() ?? string.Empty;
    }
}

public class IntToStringConverter : GenericConverter<int, string>
{
    public IntToStringConverter()
    {
        AllowUnsetValue = true;
        UnsetValue = "N/A";
    }

    public override string Convert(int source, CultureInfo culture)
    {
        return source.ToString();
    }
}

public class NumberToStringConverter : GenericConverter<double, string, string>
{
    public override string Convert(double source, string format, CultureInfo culture)
    {
        return source.ToString(format, culture);
    }
}

public class MultiStringConcatenator : GenericMultiConverter<string, string>
{
    public string Separator { get; set; } = " ";

    public override string Convert(string[] source, CultureInfo culture)
    {
        return string.Join(Separator, source);
    }
}

public class MultiNumberFormatter : GenericMultiConverter<double, string, string>
{
    public override string Convert(double[] source, string format, CultureInfo culture)
    {
        return string.Join(", ", source.Select(n => n.ToString(format, culture)));
    }
}

var converter = new ICollectionCountToBooleanConverter
{
    ZeroValue = false,
    NotZeroValue = true,
    NullValue = false
};

