public enum Priority { [Display(Name = "Low Priority")] Low,
[Display(Name = "Medium Priority")] Medium,
[Display(Name = "High Priority")] High }

public class TaskViewModel : INotifyPropertyChanged
{
    private Priority? _priority;

    // Nullable enum - can be null, Low, Medium, or High
    public Priority? Priority
    {
        get => _priority;
        set
        {
            _priority = value;
            OnPropertyChanged();
        }
    }
}

public class FilterViewModel : INotifyPropertyChanged
{
    // null = no filter, otherwise filter by priority
    public Priority? PriorityFilter { get; set; }

    public IEnumerable<Task> FilteredTasks
    {
        get
        {
            var tasks = AllTasks;
            if (PriorityFilter.HasValue)
                tasks = tasks.Where(t => t.Priority == PriorityFilter.Value);
            return tasks;
        }
    }
}

