Console.WriteLine(converter.Convert(time, CultureInfo.CurrentCulture));
// Output: "1 day, 1 hour, 30 minutes"

// Show only 2 components
converter.NumberOfElements = 2;
Console.WriteLine(converter.Convert(time, CultureInfo.CurrentCulture));
// Output: "1 day, 1 hour"

// Show only 1 component
converter.NumberOfElements = 1;
Console.WriteLine(converter.Convert(time, CultureInfo.CurrentCulture));
// Output: "1 day"

