    private bool _isDirty;

    public bool IsDirty
    {
        get => _isDirty;
        set
        {
            _isDirty = value;
            OnPropertyChanged();
            SaveCommand.RaiseCanExecuteChanged();
        }
    }

    public GenericCommand SaveCommand { get; }

    public EditorViewModel()
    {
        SaveCommand = new GenericCommand(
            action: Save,
            canExecute: () => IsDirty
        );
    }

    private void Save()
    {
        // Save logic
        IsDirty = false;
    }
}

